/**
 * Spelling Bee Solver Engine
 *
 * Rules:
 * - Words must be at least 4 letters long
 * - Words must contain the center (required) letter
 * - Words can only use the 7 allowed letters
 * - Pangram: uses all 7 letters at least once
 */

export interface WordResult {
  word: string
  length: number
  isPangram: boolean
  score: number
}

export interface SolverResult {
  words: WordResult[]
  pangrams: WordResult[]
  totalScore: number
  wordCount: number
  pangramCount: number
}

