function canFormWord(word: string, letters: string[], required: string): boolean {
  if (word.length < 4) return false
  if (!word.includes(required)) return false
  for (const ch of word) {
    if (!letters.includes(ch)) return false
  }
  return true
}

function isPangram(word: string, letters: string[]): boolean {
  const used = new Set(word.split(''))
  return letters.every((ch) => used.has(ch))
}

function scoreWord(word: string, letters: string[]): number {
  let score = word.length === 4 ? 1 : word.length
  if (isPangram(word, letters)) {
    score += 7 // pangram bonus
  }
  return score
}

export function solveSpellingBee(
  letters: string[],
  required: string
): SolverResult {
  const results: WordResult[] = []

  for (const word of COMMON_WORDS) {
    if (canFormWord(word, letters, required)) {
      const pangram = isPangram(word, letters)
      results.push({
        word,
        length: word.length,
        isPangram: pangram,
        score: scoreWord(word, letters),
      })
    }
  }

  results.sort((a, b) => {
    if (a.isPangram !== b.isPangram) return b.isPangram ? 1 : -1
    if (a.length !== b.length) return b.length - a.length
    return a.word.localeCompare(b.word)
  })

  const pangrams = results.filter((r) => r.isPangram)
  const totalScore = results.reduce((sum, r) => sum + r.score, 0)

  return {
    words: results,
    pangrams,
    totalScore,
    wordCount: results.length,
    pangramCount: pangrams.length,
  }
}
